package sprint

import (
	"context"
	"encoding/json"
	"errors"
	"fmt"
	"os"
	"os/exec"
	"path/filepath"
	"sync"
	"sync/atomic"
	"testing"
	"time"
)

func reproFixture(t *testing.T) (string, Sprint) {
	t.Helper()
	root := t.TempDir()
	projectRoot := filepath.Join(root, "projects", "alpha")
	sprintRoot := filepath.Join(projectRoot, "sprints", "31-web")
	if err := os.MkdirAll(sprintRoot, 0o755); err != nil {
		t.Fatal(err)
	}
	if err := os.WriteFile(filepath.Join(projectRoot, "project-index.md"), []byte("# Project Index: alpha\n"), 0o644); err != nil {
		t.Fatal(err)
	}
	if err := os.WriteFile(filepath.Join(sprintRoot, "sprint-index.md"), []byte("# Sprint Index: web\n"), 0o644); err != nil {
		t.Fatal(err)
	}
	return root, Sprint{Project: "alpha", Slug: "31-web", Path: sprintRoot}
}

// Finding A: acquireVerificationFileLock stale-lock steal is not ownership-checked.
// P1 reads the dead lock; P2 steals it and installs a live lock; P1's unconditional
// os.Remove then unlinks P2's live lock and P1 creates its own. Both hold the lease.
func TestReproLeaseDualHolderTOCTOU(t *testing.T) {
	root, sp := reproFixture(t)
	lockPath := filepath.Join(root, ".ultraplan", "locks", "sprint", sp.Project+"--"+sp.Slug+".lock")
	cmd := exec.Command("true")
	if err := cmd.Run(); err != nil {
		t.Fatal(err)
	}
	deadPID := cmd.Process.Pid
	now := time.Now().UTC()
	info := verificationLockInfo{Project: sp.Project, Sprint: sp.Slug, PID: deadPID, AcquiredAt: now.Add(-time.Hour)}
	data, _ := json.Marshal(info)

	// Deterministic statement-order interleaving (scheduler may preempt between
	// any of these syscalls in production).
	if err := os.MkdirAll(filepath.Dir(lockPath), 0o755); err != nil {
		t.Fatal(err)
	}
	if err := os.WriteFile(lockPath, data, 0o644); err != nil {
		t.Fatal(err)
	}
	if _, err := readVerificationFileLock(lockPath); err != nil { // P1 observes dead owner
		t.Fatalf("P1 read: %v", err)
	}
	l2, err := acquireVerificationFileLock(root, sp, now) // P2 steals and now holds
	if err != nil {
		t.Fatalf("P2 acquire: %v", err)
	}
	if err := os.Remove(lockPath); err != nil { // P1 unlinks P2's LIVE lock
		t.Fatalf("P1 remove: %v", err)
	}
	l1, err := acquireVerificationFileLock(root, sp, now) // P1 acquires too
	if err != nil {
		t.Fatalf("P1 acquire after stealing live lock: %v", err)
	}
	if l1 == nil || l2 == nil {
		t.Fatal("expected dual holders")
	}
	releaseErr2 := l2.release() // P2 must now refuse/leak: file belongs to P1
	t.Logf("P2 release error (expected ownership mismatch or already-removed): %v", releaseErr2)
	if err := l1.release(); err != nil {
		t.Fatalf("P1 release: %v", err)
	}

	// Probabilistic hammer: concurrent acquisition against a stale lock.
	var dualHolders int32
	for round := 0; round < 400 && atomic.LoadInt32(&dualHolders) == 0; round++ {
		os.Remove(lockPath)
		os.WriteFile(lockPath, data, 0o644)
		var holders atomic.Int32
		var wg sync.WaitGroup
		start := make(chan struct{})
		for i := 0; i < 16; i++ {
			wg.Add(1)
			go func() {
				defer wg.Done()
				<-start
				if lock, err := acquireVerificationFileLock(root, sp, time.Now().UTC()); err == nil {
					cur := holders.Add(1)
					for {
						max := atomic.LoadInt32(&dualHolders)
						if cur <= max || atomic.CompareAndSwapInt32(&dualHolders, max, cur) {
							break
						}
					}
					time.Sleep(time.Millisecond)
					holders.Add(-1)
					_ = lock.release()
				}
			}()
		}
		close(start)
		wg.Wait()
	}
	if atomic.LoadInt32(&dualHolders) > 1 {
		t.Fatalf("MUTUAL EXCLUSION BROKEN: %d goroutines held the lease simultaneously", dualHolders)
	} else {
		t.Log("hammer did not reproduce dual holders naturally (deterministic sequence above stands)")
	}
}

// Finding B: Service.Status persists refreshed flow state without the mutation
// lease; its load->save window can revert a terminal attempt commit performed by
// a lease-holding writer, resurrecting the active attempt and erasing evidence.
func TestReproStatusSnapshotClobberDeterministic(t *testing.T) {
	ctx := context.Background()
	root, sp := reproFixture(t)
	now := time.Now().UTC()
	base := NewFlowState(sp, DeriveStages(sp, mustSnap(t, root, sp), nil), now)
	base.Review = &ReviewStageState{
		Status: ReviewRunning,
		Path:   ArtifactRelPath(sp, StageReview),
		ActiveAttempt: &VerificationAttempt{ID: "review-1", Status: AttemptRunning, StartedAt: now, HeartbeatAt: now, OwnerPID: os.Getpid()},
	}
	if err := SaveFlowState(root, sp, base); err != nil {
		t.Fatal(err)
	}
	prior, err := LoadFlowState(root, sp) // Status snapshot (service.go:250)
	if err != nil {
		t.Fatal(err)
	}
	reviewMD := "# Review Context\n\nplaceholder body for digest\n"
	if err := os.WriteFile(filepath.Join(sp.Path, "review.md"), []byte(reviewMD), 0o644); err != nil {
		t.Fatal(err)
	}

	svc := NewService(root)
	_, release, err := svc.acquireMutationContext(ctx, "alpha", "31-web") // writer holds lease
	if err != nil {
		t.Fatal(err)
	}
	result := ReviewResult{Project: "alpha", Sprint: "31-web", Status: ReviewCompleted, Verdict: ReviewPass, Fingerprint: "fp-terminal"}
	if err := svc.saveReviewState("alpha", "31-web", result, 1, 1); err != nil { // terminal commit under lease
		t.Fatal(err)
	}
	release()

	// Status side applies its pre-commit snapshot now (the service.go:291-294 write).
	refreshed := NewFlowState(sp, prior.Stages, time.Now().UTC())
	refreshed.Review = prior.Review
	refreshed.Smoke = prior.Smoke
	refreshed.QA = prior.QA
	if err := SaveFlowState(root, sp, refreshed); err != nil {
		t.Fatal(err)
	}

	final, err := LoadFlowState(root, sp)
	if err != nil {
		t.Fatal(err)
	}
	if final.Review == nil || final.Review.LastComplete != nil || final.Review.LastAttempt != nil || final.Review.ActiveAttempt == nil {
		t.Fatalf("expected clobbered state, got %+v", final.Review)
	}
	t.Logf("CLOBBERED: completed review evidence erased; phantom ActiveAttempt %s resurrected (owner pid %d)", final.Review.ActiveAttempt.ID, final.Review.ActiveAttempt.OwnerPID)

	vs, err := svc.VerificationStatus("alpha", "31-web")
	if err != nil {
		t.Fatal(err)
	}
	t.Logf("post-clobber verification assessment=%q next=%q", vs.Assessment, vs.NextAction)
}

func mustSnap(t *testing.T, root string, sp Sprint) ArtifactSnapshot {
	t.Helper()
	snap, err := NewFSStore(root).ReadArtifacts(sp)
	if err != nil {
		t.Fatal(err)
	}
	return snap
}

// Real-concurrency variant: hammer Status against a lease-holding writer loop.
func TestReproStatusSnapshotClobberHammer(t *testing.T) {
	ctx := context.Background()
	root, sp := reproFixture(t)
	now := time.Now().UTC()
	base := NewFlowState(sp, DeriveStages(sp, mustSnap(t, root, sp), nil), now)
	if err := SaveFlowState(root, sp, base); err != nil {
		t.Fatal(err)
	}
	if err := os.WriteFile(filepath.Join(sp.Path, "review.md"), []byte("# Review Context\nbody\n"), 0o644); err != nil {
		t.Fatal(err)
	}
	writer := NewService(root)
	statuser := NewService(root)
	stop := make(chan struct{})
	var statusErrs atomic.Int64
	go func() {
		for {
			select {
			case <-stop:
				return
			default:
			}
			if _, err := statuser.Status("alpha", "31-web"); err != nil {
				statusErrs.Add(1)
			}
		}
	}()
	clobbers := 0
	const iterations = 60
	for i := 0; i < iterations; i++ {
		_, release, err := writer.acquireMutationContext(ctx, "alpha", "31-web")
		if err != nil {
			continue
		}
		err = writer.saveReviewState("alpha", "31-web", ReviewResult{Project: "alpha", Sprint: "31-web", Status: ReviewCompleted, Verdict: ReviewPass, Fingerprint: fmt.Sprintf("fp-%d", i)}, 1, 1)
		release()
		if err != nil {
			continue
		}
		state, err := LoadFlowState(root, sp)
		if err == nil && state.Review != nil && state.Review.LastComplete != nil && state.Review.LastAttempt == nil {
			time.Sleep(2 * time.Millisecond) // give an in-flight stale Status save time to land
			state, err = LoadFlowState(root, sp)
			if err == nil && state.Review != nil && state.Review.LastComplete == nil && state.Review.LastAttempt == nil {
				clobbers++
			}
		}
	}
	close(stop)
	t.Logf("writer commits=%d observed clobbers=%d statusErrors=%d", iterations, clobbers, statusErrs.Load())
	if clobbers > 0 {
		t.Fatalf("STATUS CLOBBER OBSERVED %d/%d times without any lock violation", clobbers, iterations)
