func mustSnap(t *testing.T, root string, sp Sprint) ArtifactSnapshot {
	t.Helper()
	snap, err := NewFSStore(root).ReadArtifacts(sp)
	if err != nil {
		t.Fatal(err)
	}
	return snap
}

// Real-concurrency variant: hammer Status against a lease-holding writer loop.
func TestReproStatusSnapshotClobberHammer(t *testing.T) {
	ctx := context.Background()
	root, sp := reproFixture(t)
	now := time.Now().UTC()
	base := NewFlowState(sp, DeriveStages(sp, mustSnap(t, root, sp), nil), now)
	if err := SaveFlowState(root, sp, base); err != nil {
		t.Fatal(err)
	}
	if err := os.WriteFile(filepath.Join(sp.Path, "review.md"), []byte("# Review Context\nbody\n"), 0o644); err != nil {
		t.Fatal(err)
	}
	writer := NewService(root)
	statuser := NewService(root)
	stop := make(chan struct{})
	var statusErrs atomic.Int64
	go func() {
		for {
			select {
			case <-stop:
				return
			default:
			}
			if _, err := statuser.Status("alpha", "31-web"); err != nil {
				statusErrs.Add(1)
			}
		}
	}()
	clobbers := 0
	const iterations = 60
	for i := 0; i < iterations; i++ {
		_, release, err := writer.acquireMutationContext(ctx, "alpha", "31-web")
		if err != nil {
			continue
		}
		err = writer.saveReviewState("alpha", "31-web", ReviewResult{Project: "alpha", Sprint: "31-web", Status: ReviewCompleted, Verdict: ReviewPass, Fingerprint: fmt.Sprintf("fp-%d", i)}, 1, 1)
		release()
		if err != nil {
			continue
		}
		state, err := LoadFlowState(root, sp)
		if err == nil && state.Review != nil && state.Review.LastComplete != nil && state.Review.LastAttempt == nil {
			time.Sleep(2 * time.Millisecond) // give an in-flight stale Status save time to land
			state, err = LoadFlowState(root, sp)
			if err == nil && state.Review != nil && state.Review.LastComplete == nil && state.Review.LastAttempt == nil {
				clobbers++
			}
		}
	}
	close(stop)
	t.Logf("writer commits=%d observed clobbers=%d statusErrors=%d", iterations, clobbers, statusErrs.Load())
	if clobbers > 0 {
		t.Fatalf("STATUS CLOBBER OBSERVED %d/%d times without any lock violation", clobbers, iterations)
	}
}

// Finding C: storage.migrate leaves the legacy six-stage v2 file in place while
// making the DB authoritative; preCodeContextFlowState probes that stale FILE and
// permanently suppresses the Status refresh write, so derived stage statuses are
// never persisted again until some other writer saves.
func TestReproMigratedLegacyFileSuppressesStatusRefresh(t *testing.T) {
	root, sp := reproFixture(t)
	now := time.Now().UTC()
	stages := func(plan StageStatus) []StageState {
		out := []StageState{}
		appendStage := func(stage PlanningStage, status StageStatus) {
			out = append(out, StageState{Stage: stage, Status: status, Path: ArtifactRelPath(sp, stage)})
		}
		appendStage(StageRequirements, StatusComplete)
		appendStage(StageSprintIndex, plan)
		appendStage(StageTechnicalHandbook, plan)
		appendStage(StageAreaReasoning, plan)
		appendStage(StageReasoning, plan)
		appendStage(StagePlan, plan)
		return out
	}
	legacy := FlowState{SchemaVersion: FlowStateSchemaVersion, Project: sp.Project, Sprint: sp.Slug, UpdatedAt: now, Stages: stages(StatusMissing)}
	content, err := json.MarshalIndent(legacy, "", "  ")
	if err != nil {
		t.Fatal(err)
	}
	flowPath := filepath.Join(sp.Path, "flow-state.json")
	if err := os.WriteFile(flowPath, content, 0o644); err != nil {
		t.Fatal(err)
	}
	migrated, err := LoadFlowState(root, sp) // read-time interpretation -> 7 stages
	if err != nil {
		t.Fatal(err)
	}
	if len(migrated.Stages) != 7 {
		t.Fatalf("expected interpreted 7-stage state, got %d", len(migrated.Stages))
	}
	if err := productEnsureAndMigrate(root, sp, migrated); err != nil {
		t.Fatal(err)
	}
	inDB, err := FlowStateInDatabase(root, sp)
	if err != nil || !inDB {
		t.Fatalf("flow state not DB-authoritative: %v %v", inDB, err)
	}
	if _, err := os.Stat(flowPath); err != nil {
		t.Fatalf("migrate removed the legacy file unexpectedly: %v", err)
	}

	// User repairs planning artifacts; plan.md is now valid on disk.
	if err := os.WriteFile(filepath.Join(sp.Path, "plan.md"), []byte("# Plan\n\nwork\n"), 0o644); err != nil {
		t.Fatal(err)
	}
	svc := NewService(root)
	if _, err := svc.Status("alpha", "31-web"); err != nil {
		t.Fatalf("status: %v", err)
	}
	dbState, found, err := loadFlowStateDatabase(root, sp)
	if err != nil || !found {
		t.Fatalf("db load: found=%v err=%v", found, err)
	}
	planStatus := ""
	for _, s := range dbState.Stages {
		if s.Stage == StagePlan {
			planStatus = string(s.Status)
		}
	}
	if planStatus != string(StatusMissing) {
		t.Fatalf("expected suppressed refresh to leave plan %q in DB, got %q (defect absent?)", StatusMissing, planStatus)
	}

	// Contrast: with no legacy-shaped file present the refresh IS persisted.
	if err := os.Remove(flowPath); err != nil {
		t.Fatal(err)
	}
	if _, err := svc.Status("alpha", "31-web"); err != nil {
		t.Fatal(err)
	}
	dbState, _, err = loadFlowStateDatabase(root, sp)
	if err != nil {
		t.Fatal(err)
	}
	for _, s := range dbState.Stages {
		if s.Stage == StagePlan && s.Status != StatusComplete {
			t.Fatalf("contrast case failed: plan still %q after removing legacy file", s.Status)
		}
	}
}

